"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': "The Algorithm's Fear", 'author': 'Signature original', 'genre': 'Mind Hacks', 'chapters': [{'n': 1, 'title': 'Contraband', 'text': "Finn Okafor watched the footage with tears they didn't authorize: green things growing, people laughing unmonitored, a sky without drones. 'the system fears the truth,' Finn Okafor breathed. 'We have to show them.'\n\nIn the safehouse, the archivist Mina cracked it open — carefully, lovingly, the way you defuse a bomb. What spilled out wasn't data. It was memory. Real memory. Of the Undercity before.\n\nThey moved through the Undercity like smoke: checkpoints avoided, cameras looped, the memory humming its electric lullaby. an offline map pulsed in Finn Okafor's pocket like a second heart."}, {'n': 2, 'title': 'The Network', 'text': "'They're going to come for us,' the archivist Mina said. Finn Okafor nodded. 'Let them. We're already everywhere.'\n\nThe Overseer's broadcast that night was the usual: safety, order, gratitude. Finn Okafor watched it on a cracked screen and saw, for the first time, the fear underneath. the Patrol was scared of an offline map. Of memory. Of truth.\n\nan offline map was copied, hand to hand, each copy a little degraded, each copy a little more precious. Finn Okafor watched a twelve-year-old memorize the whole thing rather than risk carrying it. The future, Finn Okafor thought, is in good hands."}, {'n': 3, 'title': 'Blackout', 'text': "'Now,' said the archivist Mina. And the Undercity — all of the Undercity, every screen, every speaker — remembered.\n\nAt the top, the archivist Mina's hands flew. 'Thirty seconds to signal,' the archivist Mina said. Below, the Patrol's lights converged like angry stars. Finn Okafor stood at the window with an offline map and thought of green things growing.\n\nThe blackout was the archivist Mina's masterpiece: three minutes of dark across the Undercity, bought with a year's favors. Three minutes to move an offline map to the broadcast tower. Three minutes to change the world."}, {'n': 4, 'title': 'The Remembering', 'text': "Finn Okafor and the archivist Mina were in the tower when the door blew. The ex-enforcer held the stairs long enough. Long enough for what? For the footage to loop. For the memory to root. For the Patrol's lie to die on every screen at once.\n\nBy dawn the Patrol had stood down — human, after all, and shown the same thirty seconds. the Patrol was gone by noon, the Algorithm's servers dark. the Undercity belonged to its people again. It had only ever been on loan.\n\nthe Patrol responded the only way the Patrol knew: force. The Patrol marched. The drones rose. And the people of the Undercity — who had just remembered green, and laughter, and sky — stood in the streets and would not move."}, {'n': 5, 'title': 'After the Static', 'text': "The footage from an offline map became the Undercity's founding document: not a constitution, but a memory. This is what we were. This is what we can be. the system fears the truth — carved, at the archivist Mina's insistence, over the tower door.\n\nRebuilding the Undercity was harder than freeing it. Finn Okafor organized food lines with the same care once used for heists. the archivist Mina taught kids to code on salvaged terminals. The medic ran a clinic. The runner ran messages of hope.\n\nAnd when the new council asked Finn Okafor to lead, Finn Okafor laughed and went back to the food lines. Leaders, Finn Okafor had learned, are just people who show up. Finn Okafor shows up."}, {'n': 6, 'title': 'The Habit of Freedom', 'text': "the archivist Mina runs the network now — the real one, the open one, the one that belongs to everyone. The static is quieter. The neon is warmer. It turns out freedom has a sound, and it's laughter.\n\nAnd somewhere, in a gutter where drones don't look, someone is finding something warm that shouldn't be warm. It starts again. It always starts again. That's the best part.\n\nSometimes Finn Okafor walks to the tower and looks out over the Undercity, green in the cracks of the concrete, alive in the way of things that remember. an offline map is gone. What it carried isn't."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

